<main class="product-detail-page"><section class="page-hero"><div class="container"><h1><?=e($product['title'])?></h1><p class="lead"><?=e(implode(' / ',array_column($relations,'title')))?></p></div></section><section class="product-detail-section"><div class="container"><div class="product-detail-grid"><div><div class="product-detail-media"><?php if($product['image_id']):?><?=media_img($product['image_id'],$product['title'],'cms-product-main',false)?><?php else:?><div class="product-detail-placeholder"><i class="fa-solid fa-box"></i></div><?php endif?></div><?php if($images):?><div class="cms-product-thumbs"><?php if($product['image_id']):?><button type="button" data-product-image="<?=e(media_url($product['image_id']))?>" aria-label="<?=e($product['title'])?>"><?=media_img($product['image_id'],$product['title'])?></button><?php endif?><?php foreach($images as $image):?><button type="button" data-product-image="<?=e(media_url($image['image_id']))?>" aria-label="<?=e($image['title']?:$product['title'])?>"><?=media_img($image['image_id'],$image['title']?:$product['title'])?></button><?php endforeach?></div><?php endif?></div><div class="product-detail-copy"><?php if($product['badge']):?><span class="product-detail-badge"><?=e($product['badge'])?></span><?php endif?><h2><?=e($product['title'])?></h2><div class="rich-text"><?=rich($product['description'])?></div><dl class="product-detail-meta"><?php foreach($relations as $module=>$relation):?><div><dt><?=text(['brands'=>'brand','categories'=>'category','subcategories'=>'subcategory'][$module])?></dt><dd><?=e($relation['title'])?></dd></div><?php endforeach?></dl><?php if($specifications):?><h3><?=text('specifications')?></h3><dl class="product-detail-meta"><?php foreach($specifications as $spec):?><div><dt><?=e($spec['title'])?></dt><dd><?=e($spec['value'])?></dd></div><?php endforeach?></dl><?php endif?><div class="product-detail-actions"><a class="btn btn-primary" href="<?=e(cms_url('/contact/?'.http_build_query(['requirement'=>$product['title'],'message'=>$product['title']."\n".implode(' / ',array_column($relations,'title'))]).'#contact-form-card'))?>"><?=text('request_quote')?></a><?php if($product['external_url']):?><a class="btn btn-outline-primary" href="<?=e(cms_url($product['external_url']))?>" target="_blank" rel="noopener noreferrer"><?=e($product['button_label'])?></a><?php endif?></div></div></div><?php if($related):?><div class="related-products"><h2><?=text('related_products')?></h2><div class="catalog-products-grid"><?php foreach($related as $product)cms_view('public/product-card',compact('product'));?></div></div><?php endif?></div></section></main>
